head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDMGT50308";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return " " + String(dma_disclosureLaw.get("lawTitle")) + " (개정일 " + String((String(String(dma_disclosureLaw.get("lawAmendDd")) == null ? '' : String(dma_disclosureLaw.get("lawAmendDd"))) === '' ? '' : String("yyyy-MM-dd").replace(/yyyy/g, String(dma_disclosureLaw.get("lawAmendDd")).slice(0,4)).replace(/MM/g, String(dma_disclosureLaw.get("lawAmendDd")).slice(4,6)).replace(/dd/g, String(dma_disclosureLaw.get("lawAmendDd")).slice(6,8)).replace(/HH/g, String(dma_disclosureLaw.get("lawAmendDd")).slice(8,10)).replace(/mm/g, String(dma_disclosureLaw.get("lawAmendDd")).slice(10,12)).replace(/ss/g, String(dma_disclosureLaw.get("lawAmendDd")).slice(12,14)))) + ") "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.list();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50308.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt50308.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_1_onsubmit
 * @description form_1 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_1_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50308.form_1_onsubmit' }); }
};

/**
 * @method
 * @name indexTab_onclick
 * @description 「[없음]」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.indexTab_onclick = async function(e){
    try {
        await scwin.list()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50308.indexTab_onclick' }); }
};

/**
 * @method
 * @name contentTab_onclick
 * @description 「[없음]」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.contentTab_onclick = async function(e){
    try {
        await scwin.lawAll()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50308.contentTab_onclick' }); }
};

/**
 * @method
 * @name img_39_onclick
 * @description img_39 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_39_onclick = function(e){
    try {
        scwin.addDetail()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50308.img_39_onclick' }); }
};

/**
 * @method
 * @name img_40_onclick
 * @description img_40 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_40_onclick = function(e){
    try {
        scwin.modLawItm()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50308.img_40_onclick' }); }
};

/**
 * @method
 * @name img_53_onclick
 * @description img_53 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_53_onclick = function(e){
    try {
        scwin.lawList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50308.img_53_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_List_xhr
 * @description List xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_List_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr", unresolved: "action:self_submit:tx_fn_List_xhr" };
};

/**
 * @method
 * @name tx_fn_LawAll_xhr
 * @description Law All xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_LawAll_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_LawAll_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_LawAll_xhr", unresolved: "action:self_submit:tx_fn_LawAll_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    $c.util.getComponent('indexTab').setSrc("/img/filing/body/tab_index_selected.gif");
    $c.util.getComponent('contentTab').setSrc("/img/filing/body/tab_content_unselected.gif");
    scwin.form_listForm.action = "/filing/onlineDisclosureLaw.do";
    $c.util.getComponent('dma_ListXhrReq').set('method', "findDisclosureLawItems");
    $c.util.getComponent('txt_lawListDiv').setValue(await scwin.tx_fn_List_xhr());
};

/**
 * @method
 * @name lawAll
 * @description law All 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.lawAll = async function () {
    $c.util.getComponent('indexTab').setSrc("/img/filing/body/tab_index_unselected.gif");
    $c.util.getComponent('contentTab').setSrc("/img/filing/body/tab_content_selected.gif");
    scwin.form_listForm.action = "/filing/onlineDisclosureLaw.do";
    $c.util.getComponent('dma_ListXhrReq').set('method', "findDisclosureLawAllItems");
    $c.util.getComponent('txt_lawListDiv').setValue(await scwin.tx_fn_LawAll_xhr());
};

/**
 * @method
 * @name lawContentDetail
 * @description law Content Detail 처리
 * @param {*} lawItmSeq lawItmSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.lawContentDetail = async function (lawItmSeq) {
    const _url = "/ui/jsp/ULDMGT50309.xml?method=findDisclosureLawItemContent" + "&lawNo=" + dma_disclosureLaw.get("lawNo") + "&lawItmSeq=" + lawItmSeq;
    await $c.win.openPopup(_url, { id: "lawContentPop", popupName: "lawContentPop", width: "700", height: "650" }, {});
};

/**
 * @method
 * @name addDetail
 * @description add Detail 처리
 * @returns {void}
 * @hidden N
 */
scwin.addDetail = function () {
    const _url = "/filing/updateOnlineDisclosureLawDetail.do?method=findDisclosureLawArticles" + "&lawNo=" + $c.util.getComponent('dma_ListXhrReq').get('lawNo') + "&dtruleLawNo=" + $c.util.getComponent('dma_ListXhrReq').get('dtruleLawNo');
    $c.win.moveUrl(_url);
};

/**
 * @method
 * @name modLawItm
 * @description mod Law Itm 처리
 * @returns {void}
 * @hidden N
 */
scwin.modLawItm = function () {
    const _url = "/filing/updateOnlineDisclosureLaw.do?method=prepareUpdateDisclosureLawItems" + "&lawNo=" + $c.util.getComponent('dma_ListXhrReq').get('lawNo') + "&mode=update";
    $c.win.moveUrl(_url);
};

/**
 * @method
 * @name lawAddrule
 * @description law Addrule 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.lawAddrule = async function () {
    const _url = "/ui/jsp/ULDMGT50309.xml?method=findDisclosureLawAddruleContent" + "&lawNo=" + dma_disclosureLaw.get("lawNo") + "";
    await $c.win.openPopup(_url, { id: "lawAddrulePop", popupName: "lawAddrulePop" }, {});
};

/**
 * @method
 * @name lawList
 * @description law List 처리
 * @returns {void}
 * @hidden N
 */
scwin.lawList = function () {
    $c.win.moveUrl("/filing/disclosureLaw.do");
};
